```yaml
name: Triage Issue

on:
  issues:
    types: [opened]

permissions:
  issues: write

jobs:
  triage:
    runs-on: ubuntu-latest
    steps:
      - name: Triage Issue
        uses: actions/github-script@v7
        with:
          script: |
            const issue = context.payload.issue;
            const title = issue.title.toLowerCase();
            const body = issue.body ? issue.body.toLowerCase() : '';
            const text = `${title} ${body}`;

            // Define keywords
            const bugKeywords = ['bug', 'error', 'crash', 'broken', 'fix', 'fail', 'wrong', 'regression'];
            const featureKeywords = ['feat', 'feature', 'enhancement', 'add', 'implement', 'request', 'improve'];
            const highPriorityKeywords = ['critical', 'urgent', 'blocker', 'blocking', 'severe', 'p0', 'p1'];
            const lowPriorityKeywords = ['minor', 'trivial', 'nice to have', 'low priority', 'p3', 'p4'];

            // Helper to check if any keyword exists in text
            const hasKeyword = (keywords) => keywords.some(k => text.includes(k));

            // Determine Type Label
            let typeLabel = 'feature-request';
            if (hasKeyword(bugKeywords)) {
              typeLabel = 'bug';
            } else if (hasKeyword(featureKeywords)) {
              typeLabel = 'feature-request';
            } else {
              // Fallback to feature-request if neither matches
              typeLabel = 'feature-request';
            }

            // Determine Priority Label
            let priorityLabel = 'priority: medium';
            if (hasKeyword(highPriorityKeywords)) {
              priorityLabel = 'priority: high';
            } else if (hasKeyword(lowPriorityKeywords)) {
              priorityLabel = 'priority: low';
            }

            // Define labels to ensure exist
            const labelsToEnsure = [
              { name: 'bug', color: 'd73a4a' },
              { name: 'feature-request', color: 'a2eeef' },
              { name: 'priority: high', color: 'b60205' },
              { name: 'priority: medium', color: 'fbca04' },
              { name: 'priority: low', color: '0e8a16' }
            ];

            // Bootstrap missing labels
            for (const labelDef of labelsToEnsure) {
              try {
                await github.rest.issues.getLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  name: labelDef.name
                });
              } catch (error) {
                if (error.status === 404) {
                  await github.rest.issues.createLabel({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    name: labelDef.name,
                    color: labelDef.color
                  });
                } else {
                  throw error;
                }
              }
            }

            // Apply labels
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issue.number,
              labels: [typeLabel, priorityLabel]
            });
